#include <vector>

class Solution {
public:
    std::vector<std::vector<int>> findPath(std::vector<std::vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        int total = m * n;
        std::vector<std::vector<int>> path;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        auto dfs = [&](auto& self, int r, int c, long long st, int v) -> bool {
            path.push_back({r, c});
            if ((int)path.size() == total) return true;

            for (int d = 0; d < 4; ++d) {
                int nr = r + dirs[d][0], nc = c + dirs[d][1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int idx = nr * n + nc;
                    if (!(st & (1LL << idx))) {
                        int val = grid[nr][nc];
                        if (val == 0 || val == v) {
                            int nv = (val == v) ? v + 1 : v;
                            if (self(self, nr, nc, st | (1LL << idx), nv)) {
                                return true;
                            }
                        }
                    }
                }
            }

            path.pop_back();
            return false;
        };

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 0 || grid[i][j] == 1) {
                    int start_v = (grid[i][j] == 1) ? 2 : 1;
                    if (dfs(dfs, i, j, 1LL << (i * n + j), start_v)) {
                        return path;
                    }
                }
            }
        }

        return {};
    }
};

import java.util.*;

class Solution {
    private int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public int[][] findPath(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int total = m * n;
        List<int[]> path = new ArrayList<>();

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 0 || grid[i][j] == 1) {
                    int startV = (grid[i][j] == 1) ? 2 : 1;
                    if (dfs(i, j, 1L << (i * n + j), startV, grid, path, m, n, total)) {
                        int[][] res = new int[total][2];
                        for (int idx = 0; idx < total; ++idx) {
                            res[idx] = path.get(idx);
                        }
                        return res;
                    }
                }
            }
        }
        return new int[0][0];
    }

    private boolean dfs(int r, int c, long st, int v, int[][] grid, List<int[]> path, int m, int n, int total) {
        path.add(new int[]{r, c});
        if (path.size() == total) return true;

        for (int[] dir : dirs) {
            int nr = r + dir[0], nc = c + dir[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                int idx = nr * n + nc;
                if ((st & (1L << idx)) == 0) {
                    int val = grid[nr][nc];
                    if (val == 0 || val == v) {
                        int nv = (val == v) ? v + 1 : v;
                        if (dfs(nr, nc, st | (1L << idx), nv, grid, path, m, n, total)) {
                            return true;
                        }
                    }
                }
            }
        }

        path.remove(path.size() - 1);
        return false;
    }
}

