var findPath = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    const total = m * n;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    const path = [];

    function dfs(r, c, st, v) {
        path.push([r, c]);
        if (path.length === total) return true;

        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                const idx = nr * n + nc;
                if (!(st & (1n << BigInt(idx)))) {
                    const val = grid[nr][nc];
                    if (val === 0 || val === v) {
                        const nv = val === v ? v + 1 : v;
                        if (dfs(nr, nc, st | (1n << BigInt(idx)), nv)) {
                            return true;
                        }
                    }
                }
            }
        }

        path.pop();
        return false;
    }

    for (let i = 0; i < m; ++i) {
        for (let j = 0; j < n; ++j) {
            if (grid[i][j] === 0 || grid[i][j] === 1) {
                const startV = grid[i][j] === 1 ? 2 : 1;
                if (dfs(i, j, 1n << BigInt(i * n + j), startV)) {
                    return path;
                }
            }
        }
    }

    return [];
};
